create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists public.organization_members(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('owner','admin','agent')),created_at timestamptz not null default now(),primary key(organization_id,user_id));
create index if not exists organization_members_user_id_idx on public.organization_members(user_id);
create table if not exists public.property_intakes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,created_by uuid not null references auth.users(id),schema_version integer not null default 1,status text not null default 'draft' check(status in('draft','ready','synced','error')),data jsonb not null default '{}'::jsonb,external_crm text,external_id text,sync_error text,synced_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists property_intakes_organization_id_idx on public.property_intakes(organization_id);create index if not exists property_intakes_created_by_idx on public.property_intakes(created_by);create index if not exists property_intakes_status_idx on public.property_intakes(status);
alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.property_intakes enable row level security;
revoke all on table public.organizations,public.organization_members,public.property_intakes from anon,authenticated;
grant select on table public.organizations to authenticated;grant select on table public.organization_members to authenticated;grant select,insert,update,delete on table public.property_intakes to authenticated;
create policy "members read organizations" on public.organizations for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=id and m.user_id=(select auth.uid())));
create policy "members read memberships" on public.organization_members for select to authenticated using(user_id=(select auth.uid()));
create policy "members read intakes" on public.property_intakes for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=property_intakes.organization_id and m.user_id=(select auth.uid())));
create policy "members create intakes" on public.property_intakes for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.organization_members m where m.organization_id=property_intakes.organization_id and m.user_id=(select auth.uid())));
create policy "members update intakes" on public.property_intakes for update to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=property_intakes.organization_id and m.user_id=(select auth.uid()))) with check(exists(select 1 from public.organization_members m where m.organization_id=property_intakes.organization_id and m.user_id=(select auth.uid())));
create policy "admins delete intakes" on public.property_intakes for delete to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=property_intakes.organization_id and m.user_id=(select auth.uid()) and m.role in('owner','admin')));
